import { readdir, readFile, mkdir, writeFile, rm, stat } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');
const banner =
  '<!-- Generated by scripts/sync-agent-config.mjs; edit .cursor/rules, .cursor/skills and .cursorignore instead. -->\n';
const ignoreBanner = '# Generated from .cursorignore; edit that file and run npm run sync:agents.\n';
const skillDestinations = ['.claude/skills', '.agents/skills'];

function parseFrontmatter(raw, file) {
  const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
  if (!match) throw new Error('Missing YAML frontmatter: ' + file);
  const fm = {};
  for (const line of match[1].split(/\r?\n/)) {
    if (!line.trim() || line.trim().startsWith('#')) continue;
    const i = line.indexOf(':');
    if (i === -1) continue;
    const key = line.slice(0, i).trim();
    let value = line.slice(i + 1).trim();
    if (value === 'true' || value === 'false') value = value === 'true';
    else if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith('[') && value.endsWith(']'))
    ) {
      value = JSON.parse(value);
    }
    fm[key] = value;
  }
  const body = match[2]
    .replace(/^<!-- Generated by scripts\/sync-agent-config\.mjs;[\s\S]*?-->\r?\n+/, '')
    .replace(/\s+$/, '\n');
  return { fm, body };
}

function scopeFromGlobs(globs) {
  if (Array.isArray(globs)) return globs.map(String);
  if (typeof globs === 'string' && globs.trim()) {
    return globs.split(',').map((s) => s.trim()).filter(Boolean);
  }
  return [];
}

function posix(relative) {
  return relative.split(path.sep).join('/');
}

function withBanner(body) {
  return banner + body;
}

function wrap(frontmatter, body) {
  return '---\n' + frontmatter + '\n---\n\n' + withBanner(body);
}

async function listNumbered(dir, ext) {
  try {
    return (await readdir(dir))
      .filter((f) => new RegExp('^\\d{2}-.*\\' + ext + '$').test(f))
      .sort();
  } catch (e) {
    if (e.code === 'ENOENT') return [];
    throw e;
  }
}

async function listSkillNames(dir) {
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch (e) {
    if (e.code === 'ENOENT') return [];
    throw e;
  }
  const names = [];
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    try {
      await stat(path.join(dir, entry.name, 'SKILL.md'));
      names.push(entry.name);
    } catch (e) {
      if (e.code !== 'ENOENT') throw e;
    }
  }
  return names.sort();
}

async function writeIfNeeded(relative, contents, stale) {
  const target = path.join(root, relative);
  let existing;
  try {
    existing = await readFile(target, 'utf8');
  } catch (e) {
    if (e.code !== 'ENOENT') throw e;
  }
  if (existing === contents) return stale;
  if (check) {
    console.error('Out of sync: ' + relative);
    return stale + 1;
  }
  if (
    existing !== undefined &&
    relative !== '.claude/settings.json' &&
    !existing.includes('Generated') &&
    !relative.startsWith('.ai/rules/') &&
    !relative.startsWith('.ai/ignore/') &&
    !['.codex/README.md', '.antigravity/README.md'].includes(relative)
  ) {
    throw new Error('Refusing to overwrite unmanaged file: ' + relative);
  }
  await mkdir(path.dirname(target), { recursive: true });
  await writeFile(target, contents, 'utf8');
  return stale;
}

async function removeIfNeeded(relative, stale) {
  const target = path.join(root, relative);
  try {
    await stat(target);
  } catch (e) {
    if (e.code === 'ENOENT') return stale;
    throw e;
  }
  if (check) {
    console.error('Stale: ' + relative);
    return stale + 1;
  }
  await rm(target, { recursive: true, force: true });
  return stale;
}

async function syncSkillTree(srcDir, destDir, stale) {
  const files = [];
  async function walk(current, rel = '') {
    const entries = await readdir(current, { withFileTypes: true });
    for (const entry of entries) {
      const nextRel = rel ? rel + '/' + entry.name : entry.name;
      const full = path.join(current, entry.name);
      if (entry.isDirectory()) await walk(full, nextRel);
      else files.push(nextRel);
    }
  }
  await walk(srcDir);
  for (const file of files.sort()) {
    const contents = await readFile(path.join(srcDir, file));
    const destFile = path.join(destDir, file);
    let existing;
    try {
      existing = await readFile(destFile);
    } catch (e) {
      if (e.code !== 'ENOENT') throw e;
    }
    if (existing && Buffer.compare(existing, contents) === 0) continue;
    if (check) {
      console.error('Out of sync: ' + posix(path.relative(root, destFile)));
      stale += 1;
      continue;
    }
    await mkdir(path.dirname(destFile), { recursive: true });
    await writeFile(destFile, contents);
  }
  return stale;
}

const cursorFiles = await listNumbered(path.join(root, '.cursor/rules'), '.mdc');
if (!cursorFiles.length) throw new Error('No Cursor rules found in .cursor/rules.');

const rules = [];
for (const file of cursorFiles) {
  const name = file.slice(0, -4);
  const raw = await readFile(path.join(root, '.cursor/rules', file), 'utf8');
  const { fm, body } = parseFrontmatter(raw, file);
  const title = typeof fm.description === 'string' ? fm.description : '';
  const always = fm.alwaysApply === true;
  const scope = scopeFromGlobs(fm.globs);
  if (!title) throw new Error('Cursor rule is missing description: ' + file);
  if (!always && !scope.length) throw new Error('Scoped Cursor rule is missing globs: ' + file);
  if (!body.trim()) throw new Error('Cursor rule is empty: ' + file);
  rules.push({ name, file, title, always, scope, body });
}

const core = rules.filter((r) => r.always).map((r) => r.name);
const index = rules
  .map((r) => '- .ai/rules/' + r.name + '.md - ' + r.title)
  .join('\n');
const bootstrap =
  '# InvoiceUI agent instructions\n\n' +
  'Follow these rules for this project. Read relevant detailed topics below only when needed; do not load every agent adapter.\n\n' +
  rules
    .filter((r) => r.always)
    .map((r) => r.body)
    .join('\n') +
  '\n## Topic index (paths relative to project root)\n\n' +
  index +
  '\n';

const outputs = new Map();
outputs.set('AGENTS.md', banner + bootstrap);
outputs.set(
  'CLAUDE.md',
  banner +
    '# InvoiceUI\n\nFollow the numbered topics in .claude/rules. Always-on files cover project scope, collaboration, the five-library UI requirement, rule maintenance and punctuation. Path-scoped files load with matching edits. Do not reread every adapter.\n',
);
outputs.set('GEMINI.md', banner + bootstrap);
outputs.set('.github/copilot-instructions.md', banner + bootstrap);
outputs.set('.junie/AGENTS.md', banner + bootstrap);
outputs.set('.aider.conf.yml', '# Generated; project conventions only.\nread:\n  - AGENTS.md\n');

const plainRuleDirs = [
  '.ai/rules',
  '.clinerules',
  '.roo/rules',
  '.kilocode/rules',
  '.amazonq/rules',
  '.codex/rules',
  '.antigravity/rules',
  '.junie/rules',
];
const triggerRuleDirs = ['.windsurf/rules', '.agents/rules'];

for (const rule of rules) {
  const body = rule.body;
  for (const dir of plainRuleDirs) {
    outputs.set(dir + '/' + rule.name + '.md', withBanner(body));
  }
  outputs.set(
    '.claude/rules/' + rule.name + '.md',
    rule.always
      ? withBanner(body)
      : wrap('alwaysApply: false\npaths: ' + rule.scope.join(','), body),
  );
  const triggerFm = rule.always
    ? 'trigger: always_on'
    : 'trigger: glob\nglobs: ' + rule.scope.join(',');
  for (const dir of triggerRuleDirs) {
    outputs.set(dir + '/' + rule.name + '.md', wrap(triggerFm, body));
  }
  outputs.set(
    '.continue/rules/' + rule.name + '.md',
    wrap(
      rule.always
        ? 'name: ' + JSON.stringify(rule.title) + '\nalwaysApply: true'
        : 'name: ' +
            JSON.stringify(rule.title) +
            '\nalwaysApply: false\nglobs:\n' +
            rule.scope.map((p) => '  - ' + JSON.stringify(p)).join('\n'),
      body,
    ),
  );
  outputs.set(
    '.augment/rules/' + rule.name + '.md',
    wrap(
      rule.always
        ? 'type: always_apply'
        : 'type: glob\nglobs:\n' + rule.scope.map((p) => '  - ' + JSON.stringify(p)).join('\n'),
      body,
    ),
  );
}

outputs.set(
  '.codex/README.md',
  '# Codex configuration\n\nCodex loads the project-root AGENTS.md. Numbered copies of the Cursor rules are also in .codex/rules. This README is documentation, not a second rule loader. No project_doc override, model, approval or sandbox settings are imposed. No undocumented .codexignore is created; use the shared ignore policy as agent guidance and the existing Git exclusions for normal searches.\n',
);
outputs.set(
  '.antigravity/README.md',
  '# Antigravity configuration\n\nNative workspace rules are in .agents/rules. Numbered copies are also in .antigravity/rules. This directory records the mapping. No undocumented .antigravityignore is created. Shared ignore policy is agent guidance; inspect your installed version\'s file access settings before relying on exclusion enforcement.\n',
);

const cursorIgnore = await readFile(path.join(root, '.cursorignore'), 'utf8');
const ignoreBody = cursorIgnore.replace(/^# Generated from \S+;.*\n/, '');
const ignore = ignoreBanner + ignoreBody;
for (const file of [
  '.ai/ignore/common.ignore',
  '.geminiignore',
  '.aiexclude',
  '.clineignore',
  '.rooignore',
  '.kilocodeignore',
  '.codeiumignore',
  '.continueignore',
  '.aiderignore',
  '.aiignore',
  '.augmentignore',
]) {
  outputs.set(file, ignore);
}

const secretPatterns = [
  '/**/.env',
  '/**/.env.local',
  '/**/.env.*.local',
  '/**/.env.production',
  '/**/.env.development',
  '/**/.env.test',
  '/**/.dev.vars',
  '/**/.dev.vars.local',
  '/**/.dev.vars.production',
  '/**/.dev.vars.development',
  '/**/.neon/**',
  '/**/.wrangler/**',
  '/**/secrets/**',
  '/**/.secrets/**',
  '/**/credentials/**',
  '/**/*.pem',
  '/**/*.key',
  '/**/*.p12',
  '/**/*.pfx',
  '/**/.npmrc',
];
const settingsPath = path.join(root, '.claude/settings.json');
let settings = {};
try {
  settings = JSON.parse(await readFile(settingsPath, 'utf8'));
} catch (e) {
  if (e.code !== 'ENOENT') throw e;
}
settings.permissions ??= {};
settings.permissions.deny = [
  ...new Set([...(settings.permissions.deny ?? []), ...secretPatterns.map((p) => 'Read(' + p + ')')]),
];
outputs.set('.claude/settings.json', JSON.stringify(settings, null, 2) + '\n');

let stale = 0;
for (const [relative, contents] of outputs) stale = await writeIfNeeded(relative, contents, stale);

const keepRules = new Set(rules.map((r) => r.name + '.md'));
const generatedRuleDirs = [
  ...plainRuleDirs,
  ...triggerRuleDirs,
  '.claude/rules',
  '.continue/rules',
  '.augment/rules',
];
for (const dir of generatedRuleDirs) {
  for (const file of await listNumbered(path.join(root, dir), '.md')) {
    if (!keepRules.has(file)) stale = await removeIfNeeded(dir + '/' + file, stale);
  }
  stale = await removeIfNeeded(dir + '/00-project-rules.md', stale);
}

const skills = await listSkillNames(path.join(root, '.cursor/skills'));
for (const dest of skillDestinations) {
  const destRoot = path.join(root, dest);
  for (const name of skills) {
    stale = await syncSkillTree(path.join(root, '.cursor/skills', name), path.join(destRoot, name), stale);
  }
  for (const extra of await listSkillNames(destRoot)) {
    if (!skills.includes(extra)) stale = await removeIfNeeded(posix(path.join(dest, extra)), stale);
  }
}

if (stale) process.exitCode = 1;
else {
  console.log(
    (check ? 'Verified ' : 'Synced ') +
      outputs.size +
      ' agent configuration files; ' +
      rules.length +
      ' Cursor rules; ' +
      skills.length +
      ' skills; ' +
      core.length +
      ' always-on topics.',
  );
}
